do $$
declare
  v_owner  uuid := 'c9827bd9-1614-4c51-bd25-762d3ae0cac0';
  v_client uuid := (select c.id from dma.clients c join platform.tenants t on t.id=c.tenant_id
                    where t.slug='herman-legacy-digital' and c.slug='venuewise');
  v_ten    uuid := (select id from platform.tenants where slug='herman-legacy-digital');
  v_off    uuid := (select o.id from dma.offerings o where o.client_id=v_client and o.name='HomeHuddle');
  s_umbrella uuid; s_multisport uuid; s_multiathlete uuid; s_hockey uuid; s_baseball uuid; s_general uuid;
begin
  if v_off is null then raise exception 'HomeHuddle offering not found'; end if;

  on conflict do nothing;

   values (v_ten,v_client,v_off,'Sports families','Households with one or more children in organized sports.','Umbrella hypothesis; HomeHuddle is purpose-built for sports families (venuewise.net).','supported','medium','ai_inferred','needs_review',v_owner)
   returning id into s_umbrella;
   returning id into s_multisport;
   returning id into s_multiathlete;
   returning id into s_hockey;
   returning id into s_baseball;
   returning id into s_general;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  select v_ten,v_client,v_off,d.seg, d.fs,
         (dma.compute_opportunity_score(d.fs)->>'weighted_score')::int,
         d.conf::dma.confidence, d.rec::dma.opportunity_recommendation, d.rat, d.ev,
         'ai_inferred','needs_review',v_owner,v_owner
  from (values
    (s_multisport,'{"product_fit":90,"problem_severity":75,"audience_size":85,"reachability":75,"problem_frequency":80,"competitive_intensity":45,"willingness_to_adopt":65,"conversion_potential":65,"retention_potential":70,"acquisition_cost":40}'::jsonb,'medium','test','Largest high-fit slice (65% of sports kids are multi-sport); HomeHuddle aggregation wedge directly addresses the many-apps+group-texts pain; efficiently reachable. Watch emerging aggregator (Onsides).',5),
    (s_multiathlete,'{"product_fit":88,"problem_severity":78,"audience_size":75,"reachability":75,"problem_frequency":80,"competitive_intensity":45,"willingness_to_adopt":65,"conversion_potential":65,"retention_potential":72,"acquisition_cost":40}'::jsonb,'low','test','Pain compounds across children/teams; very strong fit for a household aggregator. Audience overlaps multi-sport; confidence lower pending sizing.',3),
    (s_hockey,'{"product_fit":80,"problem_severity":90,"audience_size":45,"reachability":80,"problem_frequency":85,"competitive_intensity":65,"willingness_to_adopt":60,"conversion_potential":75,"retention_potential":75,"acquisition_cost":55}'::jsonb,'medium','test','Highest problem severity + willingness to pay and very concentrated/locally reachable (Buffalo beachhead). Smaller audience and entrenched team apps temper it; strong first test despite lower TAM.',4),
    (s_baseball,'{"product_fit":82,"problem_severity":82,"audience_size":60,"reachability":78,"problem_frequency":78,"competitive_intensity":70,"willingness_to_adopt":60,"conversion_potential":70,"retention_potential":72,"acquisition_cost":50}'::jsonb,'low','research_further','Large, tournament-heavy audience, but GameChanger is deeply entrenched (high competitive intensity). Research differentiation before testing.',3),
    (s_general,'{"product_fit":30,"problem_severity":55,"audience_size":90,"reachability":50,"problem_frequency":70,"competitive_intensity":85,"willingness_to_adopt":45,"conversion_potential":40,"retention_potential":55,"acquisition_cost":65}'::jsonb,'medium','deprioritize','Huge audience but low product fit (no sports-sync advantage) against entrenched general calendars. Deprioritize for HomeHuddle wedge.',2)
  ) as d(seg, fs, conf, rec, rat, ev)
  on conflict (segment_id) do nothing;
end $$;