  insert into dma.customer_problems (tenant_id,client_id,offering_id,segment_id,problem,description,severity,frequency,source_id,confidence,provenance,verification,created_by) values
   (v_ten,v_client,v_off,s_multisport,'Juggling multiple team apps + group texts','Each team/sport lives in its own app (TeamSnap, GameChanger, LeagueApps) plus group texts; no single family view.','high','constant',(select id from dma.research_sources where url='https://www.ezfacility.com/blog/best-youth-sports-team-management-apps/'),'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multisport,'No single household view of all kids games/practices','Parents cannot see one merged calendar across children, teams and sports.','high','constant',(select id from dma.research_sources where url='https://venuewise.net/'),'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multiathlete,'Schedule conflicts across kids and venues','Overlapping games/practices at different venues force triage and carpooling logistics.','high','frequent',null,'low','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_hockey,'High-stakes travel logistics','Weekend tournaments, long drives, hotels; a missed update is costly.','high','frequent',(select id from dma.research_sources where url='https://scout-elite.com/blog/2026/05/20/how-much-does-youth-hockey-cost/'),'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_general,'General family scheduling clutter','Work, school and activities to coordinate — but well served by existing family calendars.','medium','frequent',(select id from dma.research_sources where url='https://www.developgoodhabits.com/family-calendar-apps/'),'medium','ai_inferred','needs_review',v_owner)
