  insert into dma.market_signals (tenant_id,client_id,offering_id,segment_id,claim,evidence,signal_type,source_id,method,confidence,observed_on,provenance,verification,created_by) values
   (v_ten,v_client,v_off,s_multisport,'Multi-sport participation is the norm','65% of sports-playing kids play >=2 sports; 30% play >=3.','supporting',(select id from dma.research_sources where url='https://pro.morningconsult.com/analysis/americans-youth-sport-participation-2025'),'web_search','medium','2025-01-01','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_umbrella,'Large, growing youth-sports base','U.S. youth sports participation ~58% (2024).','supporting',(select id from dma.research_sources where url='https://projectplay.org/state-of-play-2025/participation-trends'),'web_search','high','2025-01-01','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_umbrella,'Families already spend meaningfully on sports','Avg ~$1,016/yr on a child primary sport, +46% since 2019 — willingness-to-spend signal.','supporting',(select id from dma.research_sources where url='https://youthsportsbusinessreport.com/youth-sports-hits-record-participation-but-46-cost-surge-and-widening-income-gap-threaten-growth/'),'web_search','medium','2025-01-01','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multisport,'The coordination problem is real and unserved','Parents juggle multiple team apps + group texts; general calendars do not sync sports.','supporting',(select id from dma.research_sources where url='https://www.ezfacility.com/blog/best-youth-sports-team-management-apps/'),'web_search','medium','2026-01-01','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multisport,'A direct-competitor pattern is emerging','Onsides is a parent-first aggregator doing the same "pull events into one place" play.','weakening',(select id from dma.research_sources where url='https://www.buyingsandlot.com/p/the-new-youth-sports-app-for-overwhelmed-parentst'),'web_search','medium','2025-01-01','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_hockey,'Travel families have acute, high-cost coordination','Travel hockey $2k-$13k/season, Sep-Mar, weekend tournaments — severe pain, high willingness to pay.','supporting',(select id from dma.research_sources where url='https://scout-elite.com/blog/2026/05/20/how-much-does-youth-hockey-cost/'),'web_search','medium','2026-05-20','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_umbrella,'Sports parents are efficiently reachable','Concentrated in Facebook/Instagram/TikTok, league email, team apps, local SEO and community partnerships.','supporting',(select id from dma.research_sources where url='https://www.jerseywatch.com/blog/youth-sports-marketing'),'web_search','low','2025-01-01','imported','needs_review',v_owner),
   (v_ten,v_client,v_off,s_general,'General family-calendar space is crowded','Cozi/FamilyWall/Skylight/Google are entrenched; HomeHuddle sports-sync wedge does not apply here.','weakening',(select id from dma.research_sources where url='https://www.developgoodhabits.com/family-calendar-apps/'),'web_search','medium','2026-01-01','imported','needs_review',v_owner)
